-- Consulta: Gerar Temp PgLote Empresa Parceiro
-- Tipo: Acréscimo (64)
-- Parâmetros: Formulários![Pagto Lote Header]![Pagto Lote Detail].Formulário!EmpVinculada (Texto), Formulários![Pagto Lote Header]!CodigoParceiro (Texto), Formulários![Pagto Lote Header]!DataParaPagamento (Texto), Formulários![Pagto Lote Header]!Movimento.Formulário!ValorDebito (Texto), Formulários![Pagto Lote Header]!Movimento.Formulário!FinanceiraDescricao (Texto), Formulários![Pagto Lote Header]![Pagto Lote Detail].Formulário!Integracao (Texto), Formulários![Pagto Lote Header]!Movimento.Formulário!NumMovimento (Texto), Formulários![Pagto Lote Header]!Movimento.Formulário!DescricaoHistorico (Texto), Formulários![Pagto Lote Header]!Movimento.Formulário!NumDoc (Texto), Formulários![Pagto Lote Header]!Movimento.Formulário!Efetuado (Texto)
-- Descrição: 

INSERT INTO TempLoteMovContas ( EmpVinculada, CodigoParceiro, CodHistorico, DataMovto, ValorCredito, ValorDebito, Complemento, Plano3, ContaFinanceira, Confirmado, Integracao, DataPagto, DataVencto, MovPagtoLote, Observacao, NumDoc, Efetuado )
SELECT Formulários![Pagto Lote Header]![Pagto Lote Detail].Formulário!EmpVinculada AS EmpVinculada, Formulários![Pagto Lote Header]!CodigoParceiro AS CodigoParceiro, "4" AS CodHistorico, Formulários![Pagto Lote Header]!DataParaPagamento AS DataMovto, Formulários![Pagto Lote Header]!Movimento.Formulário!ValorDebito AS ValorCredito, 0 AS ValorDebito, Formulários![Pagto Lote Header]!Movimento.Formulário!FinanceiraDescricao AS Complemento, "1" AS Plano3, "1" AS ContaFinanceira, True AS Confirmado, Formulários![Pagto Lote Header]![Pagto Lote Detail].Formulário!Integracao AS Integracao, Formulários![Pagto Lote Header]!DataParaPagamento AS DataPagto, Formulários![Pagto Lote Header]!DataParaPagamento AS DataVencto, Formulários![Pagto Lote Header]!Movimento.Formulário!NumMovimento AS MovPagtoLote, "[MA]" AS Observacao, Formulários![Pagto Lote Header]!Movimento.Formulário!DescricaoHistorico & Formulários![Pagto Lote Header]!Movimento.Formulário!NumDoc AS NumDoc, Formulários![Pagto Lote Header]!Movimento.Formulário!Efetuado AS Efetuado;
